import React from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import GlassPanel from '../glass/GlassPanel';
import Reveal from '../motion/Reveal';
import { useLang } from '../../i18n/LangContext';

// Modernist's own accent ramp
const ramp = ['#4d170e', '#7c1405', '#ae1800', '#ec3013', '#ff563c', '#ff9783', '#ffc4b8'];

export const SystemSection: React.FC = () => {
  const { t } = useLang();

  return (
    <section id="sistema" className="py-5">
      <Container>
        <Reveal>
          <GlassPanel specular className="p-5">
            <Row>
              <Col lg={5} className="mb-4 mb-lg-0">
                <div className="kicker mb-2">03 · {t('system.kicker')}</div>
                <h2 className="mb-3" style={{ fontSize: 'clamp(30px, 3.4vw, 44px)', lineHeight: 1.02 }}>
                  {t('system.title')}
                </h2>
                <p className="text-dim">{t('system.p1')}</p>
                <p className="text-dim mb-0">{t('system.p2')}</p>
              </Col>
              <Col lg={7}>
                <GlassPanel variant="quiet" className="p-3 mb-3">
                  <div className="label-xs mb-3">{t('system.color')}</div>
                  <Row noGutters style={{ margin: '-3px' }}>
                    {ramp.map((hex) => (
                      <Col key={hex} style={{ padding: 3 }}>
                        <div className="swatch" style={{ background: hex }} title={hex} />
                      </Col>
                    ))}
                  </Row>
                </GlassPanel>
                <Row>
                  <Col sm={6} className="mb-3 mb-sm-0">
                    <GlassPanel variant="quiet" className="p-3 h-100">
                      <div className="label-xs mb-3">{t('system.type')}</div>
                      <div className="h2 mb-1">Aa</div>
                      <div className="text-dimmer" style={{ fontSize: '0.75rem' }}>Archivo 800 · Archivo 400</div>
                    </GlassPanel>
                  </Col>
                  <Col sm={6}>
                    <GlassPanel variant="quiet" className="p-3 h-100">
                      <div className="label-xs mb-3">{t('system.components')}</div>
                      <div className="d-flex flex-column" style={{ gap: '0.5rem' }}>
                        <span className="chip" style={{ background: 'var(--acc)', borderColor: 'var(--acc)', color: '#fff' }}>
                          {t('system.primary')}
                        </span>
                        <span className="chip">{t('system.secondary')}</span>
                      </div>
                    </GlassPanel>
                  </Col>
                </Row>
              </Col>
            </Row>
          </GlassPanel>
        </Reveal>
      </Container>
    </section>
  );
};

export default SystemSection;
